import React from 'react';
import styled, { CSSObject, StyledComponent } from 'styled-components';

import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { Button } from '../../buttons/button/Button.js';
import type { ButtonProps } from '../../buttons/button/Button.js';
import type { CSSFocusStylesObject } from '../../core/hooks/useFocusRing.js';
import { TextBaseEmphasizedStyle } from '../../core/utils/styles/text-styles.js';
import { Flex } from '../../layouts-core/flex/Flex.js';

/* Follow-ups for Team UIOps (as discussed with FaFr)*/
// TODO: Positioning issues with overlay for tooltip at window maximize / snapping etc (issue is caused by useOverlayWithTrigger() running too soon; debug: set breakpoint in hook)
// TODO: Should overlay of the tooltip be closed when hovering over the tooltip? (see TODO below)
// TODO: Extend menu item to be reusable in other components (like for example the Select component)
// TODO: Opening the context menu with keyboard (space/enter) does not show the overlay if the first item contains a tooltip. Workaround for now: setTimeout(TOOLTIP_DELAY)

// #region StyledComponents
export const StyledMenuItem = /* @__PURE__ */ styled(Flex)<{
  disabled: boolean;
  $isFocusVisible?: boolean;
  $focusStyle?: CSSFocusStylesObject;
}>(({ disabled, $isFocusVisible, $focusStyle }) => {
  const itemBaseStyle = {
    display: 'flex',
    gap: Spacings.Size8,
    backgroundColor: 'transparent',
    textAlign: 'start',
    padding: `${Spacings.Size6} ${Spacings.Size8} ${Spacings.Size6} ${Spacings.Size8}`,
    color: Colors.Text.Neutral.Default,
    cursor: 'pointer',
    borderColor: 'transparent',
    borderStyle: Borders.Style.Default,
    borderWidth: 0,
    borderRadius: Borders.Radius.Field.Default,
    '& > .item-children:first-child': {
      paddingLeft: Spacings.Size4,
    },
    '& > .item-children:last-child': {
      paddingRight: Spacings.Size4,
    },
  };

  const focusVisibleStyle = {
    color: Colors.Text.Neutral.DefaultHover,
    '&:hover': {
      color: Colors.Text.Neutral.Default,
      backgroundColor: Colors.Background.Field.Neutral.DefaultHover,
    },
  };

  const disabledStyle = {
    color: Colors.Text.Neutral.Disabled,
    cursor: 'default',
    pointerEvents: 'none',
  };

  const hoverActiveStyle = {
    '&:hover': {
      color: Colors.Text.Neutral.Default,
      backgroundColor: Colors.Background.Field.Neutral.DefaultHover,
    },
    '&:active': {
      color: Colors.Text.Neutral.Default,
      backgroundColor: Colors.Background.Field.Neutral.DefaultActive,
    },
  };
  return {
    ...itemBaseStyle,
    ...TextBaseEmphasizedStyle,
    ...($focusStyle && $focusStyle),
    ...(!disabled && $isFocusVisible && focusVisibleStyle),
    ...(disabled ? disabledStyle : hoverActiveStyle),
  } as CSSObject;
});

export const StyledMenuItemChildren = styled('div')({
  width: '100%',
});

/**
 * @internal The styled menu button. Exported for reuse (example: chart tooltip).
 */
export const StyledMenuItemButton: StyledComponent<
  <E extends React.ElementType = 'button'>(
    props: ButtonProps<E>,
  ) => React.ReactElement<
    HTMLButtonElement,
    string | React.JSXElementConstructor<HTMLButtonElement>
  > | null,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  any,
  {
    disabled: boolean;
    $isFocusVisible?: boolean;
    $focusStyle?: CSSFocusStylesObject;
  },
  never
> = /* @__PURE__ */ styled(Button)<{
  disabled: boolean;
  $isFocusVisible?: boolean;
  $focusStyle?: CSSFocusStylesObject;
}>(({ disabled, $isFocusVisible, $focusStyle }) => {
  const buttonBaseStyle = {
    textAlign: 'start',
    paddingTop: Spacings.Size6,
    paddingRight: Spacings.Size12,
    paddingBottom: Spacings.Size6,
    paddingLeft: Spacings.Size8,
    justifyContent: 'flex-start',
    color: Colors.Text.Neutral.Default,
  };
  const focusVisibleStyle = {
    color: Colors.Text.Neutral.DefaultHover,
    '&:hover': {
      backgroundColor: Colors.Background.Field.Neutral.DefaultHover,
      color: Colors.Text.Neutral.DefaultHover,
    },
  };
  const disabledStyle = {
    color: Colors.Text.Neutral.Disabled,
  };
  const hoverActiveStyle = {
    '&:hover': {
      backgroundColor: Colors.Background.Field.Neutral.DefaultHover,
      color: Colors.Text.Neutral.DefaultHover,
    },
    '&:active': {
      backgroundColor: Colors.Background.Field.Neutral.DefaultActive,
      color: Colors.Text.Neutral.DefaultActive,
    },
  };
  return {
    ...buttonBaseStyle,
    ...TextBaseEmphasizedStyle,
    ...($focusStyle && $focusStyle),
    ...(!disabled && $isFocusVisible && focusVisibleStyle),
    ...(disabled ? disabledStyle : hoverActiveStyle),
  } as CSSObject;
});
// #endregion
